import { err } from "./src/response";
import {
	handleCreateTodo,
	handleDeleteTodo,
	handleGetTodo,
	handleListTodos,
	handleUpdateTodo,
} from "./src/routes";

const port = Number(process.env.PORT) || 3000;

const server = Bun.serve({
	port,
	async fetch(req) {
		const url = new URL(req.url);
		const path = url.pathname;

		// GET /todos
		if (path === "/todos" && req.method === "GET") {
			return handleListTodos();
		}

		// POST /todos
		if (path === "/todos" && req.method === "POST") {
			return handleCreateTodo(req);
		}

		// /todos/:id routes
		const match = path.match(/^\/todos\/([^/]+)$/);
		if (match) {
			const id = match[1];
			if (req.method === "GET") return handleGetTodo(id);
			if (req.method === "PATCH") return handleUpdateTodo(id, req);
			if (req.method === "DELETE") return handleDeleteTodo(id);
		}

		return err("not found", 404);
	},
});

export { server };

#!/usr/bin/env bun
/**
 * Receipts index link-integrity guard (#269).
 *
 * Parses `.maina/receipts/index.html`, extracts every per-receipt link
 * (`href="./<64-hex>/index.html"`), and asserts:
 *   1. every linked hash directory exists on disk under `.maina/receipts/`
 *   2. each directory contains both `index.html` and `receipt.json`
 *   3. no link is duplicated
 *   4. the index file itself exists when the receipts directory does
 *
 * Exits 0 on clean, 1 on any failure (prints the offending hashes for
 * grep-to-IDE navigation). The Pages workflow runs this before staging
 * receipts under `dist/` so we never publish a 404 to mainahq.com.
 *
 * Run manually:
 *     bun scripts/check-receipts-index.ts
 *
 * CI wires this in via the docs.yml "Stage receipts" step.
 */

import { existsSync, readFileSync, statSync } from "node:fs";
import { join } from "node:path";

const RECEIPTS_DIR = ".maina/receipts";
const INDEX_PATH = join(RECEIPTS_DIR, "index.html");
const HASH_HREF = /href="\.\/([0-9a-f]{64})\/index\.html"/g;

export interface CheckResult {
	missingDirs: string[];
	missingHtml: string[];
	missingJson: string[];
	duplicateHashes: string[];
	/** Total link count seen in the index (including duplicates). Computed
	 * once during parse so the CLI doesn't have to re-read + re-regex the
	 * index file just to print the count. */
	total: number;
}

/** True when `statSync` reports a directory. Wrapped in try/catch because
 * a TOCTOU race or a permission flip between `existsSync` and `statSync`
 * would otherwise crash the guard with an unstructured throw. */
function isDirectorySafe(dir: string): boolean {
	try {
		return statSync(dir).isDirectory();
	} catch {
		return false;
	}
}

export function checkReceiptsIndex(
	indexPath: string,
	receiptsDir: string,
): CheckResult {
	const result: CheckResult = {
		missingDirs: [],
		missingHtml: [],
		missingJson: [],
		duplicateHashes: [],
		total: 0,
	};

	const html = readFileSync(indexPath, "utf-8");
	const matches = [...html.matchAll(HASH_HREF)];
	const hashes = matches.map((m) => m[1]).filter((h): h is string => !!h);
	result.total = hashes.length;

	const seen = new Set<string>();
	for (const hash of hashes) {
		if (seen.has(hash)) {
			result.duplicateHashes.push(hash);
			continue;
		}
		seen.add(hash);

		const dir = join(receiptsDir, hash);
		if (!isDirectorySafe(dir)) {
			result.missingDirs.push(hash);
			continue;
		}
		if (!existsSync(join(dir, "index.html"))) result.missingHtml.push(hash);
		if (!existsSync(join(dir, "receipt.json"))) result.missingJson.push(hash);
	}
	return result;
}

export function isClean(r: CheckResult): boolean {
	return (
		r.missingDirs.length === 0 &&
		r.missingHtml.length === 0 &&
		r.missingJson.length === 0 &&
		r.duplicateHashes.length === 0
	);
}

function reportAndExit(r: CheckResult): never {
	if (isClean(r)) {
		process.stdout.write(
			`Receipt index integrity: ${r.total} link(s) checked, all resolve.\n`,
		);
		process.exit(0);
	}
	process.stderr.write("Receipt index integrity FAILED:\n");
	// Print full hashes so the offending directory is grep-uniquely
	// identifiable — short prefixes can collide.
	for (const h of r.missingDirs) {
		process.stderr.write(`  missing directory: ${h}\n`);
	}
	for (const h of r.missingHtml) {
		process.stderr.write(`  missing index.html: ${h}\n`);
	}
	for (const h of r.missingJson) {
		process.stderr.write(`  missing receipt.json: ${h}\n`);
	}
	for (const h of r.duplicateHashes) {
		process.stderr.write(`  duplicate link: ${h}\n`);
	}
	process.exit(1);
}

if (import.meta.main) {
	if (!existsSync(RECEIPTS_DIR)) {
		// No receipts directory at all → nothing to check (e.g. fresh
		// checkout). The docs workflow has its own "fail if missing"
		// guard for the publish path; this script stays advisory here.
		process.stdout.write("Receipts directory absent — nothing to check.\n");
		process.exit(0);
	}
	if (!existsSync(INDEX_PATH)) {
		process.stderr.write(
			`Receipts directory exists but ${INDEX_PATH} is missing.\n`,
		);
		process.exit(1);
	}
	reportAndExit(checkReceiptsIndex(INDEX_PATH, RECEIPTS_DIR));
}

/**
 * `seedWiki` — sub-task 6 of `maina setup`.
 *
 * Coordinates the first wiki compile during setup with three constraints:
 *   1. **Empty repo:** skip silently, do not fabricate a success message.
 *   2. **Already present:** prompt to rebuild (interactive) or default to keep
 *      (non-interactive). We do not blow away an existing wiki without consent.
 *   3. **Time budget:** 10s in the foreground. If compile takes longer, the
 *      promise keeps running in the background and we return immediately so the
 *      wizard can finish. Background failures are logged to
 *      `.maina/logs/setup.log` (append-only) — they do not fail setup.
 *
 * The actual compile work is delegated to `wikiCompileAction({ sample: true })`
 * (see `commands/wiki/compile.ts`), which in sample mode caps the source-file
 * set so the foreground budget is realistic for moderately sized repos.
 */

import { appendFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";
import { wikiCompileAction } from "./wiki/compile";

// ── Types ───────────────────────────────────────────────────────────────────

export interface SeedWikiOptions {
	cwd: string;
	/** From `StackContext.isEmpty` — repo has no detectable source files. */
	stackIsEmpty: boolean;
	/** True when `.maina/wiki/` already exists on disk. */
	wikiAlreadyPresent: boolean;
	/** True when neither `--ci` nor `--yes` was passed. */
	interactive: boolean;
	/** True when `--yes` was passed (assume defaults). */
	yes: boolean;
	/** Foreground time budget. Defaults to 10s. */
	timeoutMs?: number;
	// ── DI for testing ──────────────────────────────────────────────────────
	compile?: (opts: {
		cwd: string;
		sample: boolean;
	}) => Promise<{ pages: number }>;
	prompt?: (msg: string) => Promise<boolean>;
	logger?: {
		info: (m: string) => void;
		warning: (m: string) => void;
		success: (m: string) => void;
	};
}

export interface SeedWikiResult {
	/** Did we actually invoke the compiler. */
	ran: boolean;
	/** Why we did not run, if applicable. */
	skipped: "empty-repo" | "user-kept" | null;
	/** Page count when known; `null` when backgrounded or errored. */
	pages: number | null;
	/** True when the compile timed out and continues in background. */
	backgrounded: boolean;
	/** Foreground error message, if compile rejected before timeout. */
	error: string | null;
}

// ── Defaults ────────────────────────────────────────────────────────────────

const DEFAULT_TIMEOUT_MS = 10_000;

const NOOP_LOGGER = {
	info: () => {},
	warning: () => {},
	success: () => {},
};

async function defaultCompile(opts: {
	cwd: string;
	sample: boolean;
}): Promise<{ pages: number }> {
	const result = await wikiCompileAction({
		cwd: opts.cwd,
		sample: opts.sample,
		json: true, // keep the wiki command quiet during setup
		full: true, // first-time seed is always a full pass
	});
	return { pages: result.articlesTotal };
}

const TIMEOUT_SENTINEL = Symbol("seedWiki.timeout");

// ── Action ──────────────────────────────────────────────────────────────────

/**
 * Run the first wiki compile. Always resolves; never throws.
 */
export async function seedWiki(opts: SeedWikiOptions): Promise<SeedWikiResult> {
	const logger = opts.logger ?? NOOP_LOGGER;
	const compile = opts.compile ?? defaultCompile;
	const timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;

	// 1. Empty repo → skip with no fake success.
	if (opts.stackIsEmpty) {
		return {
			ran: false,
			skipped: "empty-repo",
			pages: null,
			backgrounded: false,
			error: null,
		};
	}

	// 2. Wiki already present → prompt or default-keep.
	if (opts.wikiAlreadyPresent) {
		let rebuild = false;
		if (opts.interactive && opts.prompt) {
			rebuild = await opts.prompt("Wiki already exists. Rebuild?");
		} else {
			// --yes / --ci: do not destroy existing work
			rebuild = false;
		}
		if (!rebuild) {
			return {
				ran: false,
				skipped: "user-kept",
				pages: null,
				backgrounded: false,
				error: null,
			};
		}
	}

	// 3. Race the compile against the foreground budget.
	const compilePromise = compile({ cwd: opts.cwd, sample: true });

	// Keep a reference so we can attach a `.catch` for background continuation.
	// We swallow the rejection here for the race itself; the foreground arm
	// re-throws via the wrapper below to let the catch decide.
	let timeoutHandle: ReturnType<typeof setTimeout> | undefined;
	const timeoutPromise = new Promise<typeof TIMEOUT_SENTINEL>((resolve) => {
		timeoutHandle = setTimeout(() => resolve(TIMEOUT_SENTINEL), timeoutMs);
	});

	let raceWinner:
		| { kind: "compile"; value: { pages: number } }
		| { kind: "compile-error"; error: unknown }
		| { kind: "timeout" };

	try {
		const winner = await Promise.race([
			compilePromise.then(
				(value) => ({ kind: "compile" as const, value }),
				(error) => ({ kind: "compile-error" as const, error }),
			),
			timeoutPromise.then(() => ({ kind: "timeout" as const })),
		]);
		raceWinner = winner;
	} finally {
		if (timeoutHandle !== undefined) clearTimeout(timeoutHandle);
	}

	if (raceWinner.kind === "compile") {
		logger.success(`Wiki seeded (${raceWinner.value.pages} pages).`);
		return {
			ran: true,
			skipped: null,
			pages: raceWinner.value.pages,
			backgrounded: false,
			error: null,
		};
	}

	if (raceWinner.kind === "compile-error") {
		const msg =
			raceWinner.error instanceof Error
				? raceWinner.error.message
				: String(raceWinner.error);
		logger.warning(`Wiki seed failed: ${msg}`);
		return {
			ran: true,
			skipped: null,
			pages: null,
			backgrounded: false,
			error: msg,
		};
	}

	// Timeout: keep the compile running in the background, hook a logger
	// onto its eventual settlement, and return immediately.
	logger.info(
		"Wiki compile is taking longer than expected — continuing in background.",
	);
	compilePromise.catch((err: unknown) => {
		writeBackgroundLog(opts.cwd, err);
	});
	return {
		ran: true,
		skipped: null,
		pages: null,
		backgrounded: true,
		error: null,
	};
}

// ── Helpers ─────────────────────────────────────────────────────────────────

function writeBackgroundLog(cwd: string, err: unknown): void {
	try {
		const dir = join(cwd, ".maina", "logs");
		mkdirSync(dir, { recursive: true });
		const file = join(dir, "setup.log");
		const ts = new Date().toISOString();
		const msg = err instanceof Error ? (err.stack ?? err.message) : String(err);
		appendFileSync(file, `[${ts}] wiki background compile failed: ${msg}\n`);
	} catch {
		// last-resort: swallow — we cannot fail setup from a background hook.
	}
}

#!/usr/bin/env bun
/**
 * Wave 4 / G13 regression guard — scripts/check-paths.ts.
 *
 * Walks every TypeScript source file under `packages/` (excluding tests
 * and build output) and fails the build if any `join(…)` call contains
 * two literal `.maina` segments. Two literals inside a single join()
 * are the hallmark of the "double-.maina" foot-gun the wave 1–3 work
 * almost re-introduced when new callers started forwarding a
 * `mainaDir` parameter that was actually the repo root.
 *
 * Exit 0 = clean. Exit 1 = one or more matches; each printed with
 * file:line for grep-to-IDE navigation.
 *
 * Run manually:
 *     bun scripts/check-paths.ts
 *
 * CI wires this in via `bun run check:paths`.
 */

import { readdirSync, readFileSync, statSync } from "node:fs";
import { join, relative } from "node:path";

const DOUBLE_DOT_MAINA =
	/join\([^)]*["']\.maina["'][^)]*["']\.maina["'][^)]*\)/;

const ROOT = join(import.meta.dir, "..");
const ROOTS_TO_WALK = ["packages"];
const SKIP_DIRS = new Set([
	"node_modules",
	"dist",
	"build",
	".git",
	"__tests__",
	"__fixtures__",
	"coverage",
]);
const ALLOWED_EXT = new Set([".ts", ".tsx", ".mts", ".cts"]);

interface Hit {
	file: string;
	line: number;
	text: string;
}

function walk(dir: string, hits: Hit[]): void {
	let entries: string[];
	try {
		entries = readdirSync(dir);
	} catch {
		return;
	}
	for (const name of entries) {
		if (SKIP_DIRS.has(name)) continue;
		const full = join(dir, name);
		let stats: ReturnType<typeof statSync>;
		try {
			stats = statSync(full);
		} catch {
			continue;
		}
		if (stats.isDirectory()) {
			walk(full, hits);
			continue;
		}
		if (!stats.isFile()) continue;
		const dot = name.lastIndexOf(".");
		if (dot < 0) continue;
		if (!ALLOWED_EXT.has(name.slice(dot))) continue;
		scanFile(full, hits);
	}
}

function scanFile(path: string, hits: Hit[]): void {
	let body: string;
	try {
		body = readFileSync(path, "utf-8");
	} catch {
		return;
	}
	const lines = body.split(/\r?\n/);
	for (let i = 0; i < lines.length; i++) {
		const line = lines[i] ?? "";
		if (DOUBLE_DOT_MAINA.test(line)) {
			hits.push({ file: path, line: i + 1, text: line.trim() });
		}
	}
}

function main(): void {
	const hits: Hit[] = [];
	for (const rel of ROOTS_TO_WALK) {
		walk(join(ROOT, rel), hits);
	}
	if (hits.length === 0) {
		// eslint-disable-next-line no-console
		console.log("check-paths: OK — no literal `.maina/.maina/` joins found.");
		process.exit(0);
	}
	// eslint-disable-next-line no-console
	console.error(
		`check-paths: FAIL — ${hits.length} literal '.maina/.maina/' join(…) call(s) detected.`,
	);
	for (const h of hits) {
		// eslint-disable-next-line no-console
		console.error(`  ${relative(ROOT, h.file)}:${h.line}  ${h.text}`);
	}
	// eslint-disable-next-line no-console
	console.error(
		"\nFix: pass the repo root (not the `.maina` dir) and rely on the " +
			"internal `.maina/` segment. See G13 / numbering.no-double.test.ts.",
	);
	process.exit(1);
}

main();

import { describe, expect, it } from "bun:test";
import { resolveReferencedFunctions } from "../ai-review";

describe("resolveReferencedFunctions", () => {
  it("should extract function calls from added lines in diff", () => {
    const diff = `--- a/src/app.ts
+++ b/src/app.ts
@@ -10,3 +10,5 @@ function existing() {
+  const result = validateInput(data);
+  processResult(result);
   return true;`;

    const entities = [
      { name: "validateInput", kind: "function" as const, startLine: 1, endLine: 5, filePath: "src/utils.ts",
        body: "function validateInput(data: unknown) {\n  if (!data) return null;\n  return data;\n}" },
      { name: "processResult", kind: "function" as const, startLine: 10, endLine: 15, filePath: "src/utils.ts",
        body: "function processResult(result: unknown) {\n  console.log(result);\n}" },
      { name: "unusedFunction", kind: "function" as const, startLine: 20, endLine: 25, filePath: "src/other.ts",
        body: "function unusedFunction() { return 1; }" },
    ];

    const result = resolveReferencedFunctions(diff, entities);

    expect(result).toHaveLength(2);
    expect(result[0].name).toBe("validateInput");
    expect(result[1].name).toBe("processResult");
  });

  it("should cap at 3 referenced functions per file", () => {
    const diff = `--- a/src/app.ts
+++ b/src/app.ts
@@ -1,3 +1,7 @@
+  fn1();
+  fn2();
+  fn3();
+  fn4();`;

    const entities = [
      { name: "fn1", kind: "function" as const, startLine: 1, endLine: 3, filePath: "src/a.ts", body: "function fn1() {}" },
      { name: "fn2", kind: "function" as const, startLine: 1, endLine: 3, filePath: "src/b.ts", body: "function fn2() {}" },
      { name: "fn3", kind: "function" as const, startLine: 1, endLine: 3, filePath: "src/c.ts", body: "function fn3() {}" },
      { name: "fn4", kind: "function" as const, startLine: 1, endLine: 3, filePath: "src/d.ts", body: "function fn4() {}" },
    ];

    const result = resolveReferencedFunctions(diff, entities);
    expect(result).toHaveLength(3);
  });

  it("should return empty array when no functions match", () => {
    const diff = `+++ b/src/app.ts
@@ -1,1 +1,2 @@
+  const x = 42;`;

    const result = resolveReferencedFunctions(diff, []);
    expect(result).toHaveLength(0);
  });
});

/**
 * Per-phase JSON emitter for `maina setup --ci`.
 *
 * The CI mode emits one single-line JSON object per pipeline phase to stdout
 * (preflight → detect → infer → scaffold → wiki → verify → done) so an
 * orchestrator can stream-parse setup progress without screen-scraping the
 * human UX. The emitter is the *only* stdout writer in CI mode; nothing else
 * may write to stdout while a CI run is in flight.
 *
 * Pluggable via DI: tests pass a writer spy to capture lines without touching
 * `process.stdout`. Interactive mode uses `noopEmitter()` so the wizard can
 * call `emitter.phase(...)` unconditionally without polluting the TTY.
 */

// ── Types ────────────────────────────────────────────────────────────────────

export type PhaseName =
	| "preflight"
	| "detect"
	| "infer"
	| "scaffold"
	| "wiki"
	| "verify"
	| "done";

export type PhaseStatus = "ok" | "skipped" | "error" | "degraded";

export interface PhaseEvent {
	phase: PhaseName;
	status: PhaseStatus;
	// Phase-specific fields (languages, aiSource, files, pages, findings, etc.)
	[key: string]: unknown;
}

export interface SetupEmitter {
	phase(event: PhaseEvent): void;
	done(event: PhaseEvent & { phase: "done" }): void;
}

// ── Implementations ──────────────────────────────────────────────────────────

/**
 * JSON-line emitter. Writes one single-line JSON object per call via the
 * supplied writer. The default writer streams to stdout with a trailing `\n`;
 * the writer is invoked with the *raw* JSON string (no embedded newline) so
 * tests can assert each line is parseable on its own.
 */
export function jsonEmitter(
	write: (line: string) => void = (l) => {
		process.stdout.write(`${l}\n`);
	},
): SetupEmitter {
	const emit = (event: PhaseEvent): void => {
		// Force single-line output. JSON.stringify with no spacing has no
		// embedded newlines for plain values; structured fields stay compact.
		const line = JSON.stringify(event);
		write(line);
	};
	return {
		phase: emit,
		done: emit,
	};
}

/**
 * No-op emitter for interactive mode. Allows call sites to invoke
 * `emitter.phase(...)` unconditionally.
 */
export function noopEmitter(): SetupEmitter {
	return {
		phase: () => {},
		done: () => {},
	};
}

