/**
 * W1: install.sh emits well-known exit codes and a copy-pasteable PATH hint.
 *
 * Runs install.sh with a crafted PATH containing a fake `bun` that we control,
 * then asserts the exit code and stderr/stdout contents. No Docker required.
 *
 * Exit codes:
 *   10 — no package manager found
 *   11 — install command failed
 *   12 — install succeeded but `maina` is not on PATH
 *   0  — `maina` is on PATH
 */

import { afterEach, beforeEach, describe, expect, test } from "bun:test";
import {
	chmodSync,
	existsSync,
	mkdirSync,
	rmSync,
	writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";

const INSTALL_SH = resolve(import.meta.dir, "../../../..", "install.sh");

function makeTmpBinDir(): string {
	const dir = join(
		tmpdir(),
		`maina-install-bin-${Date.now()}-${Math.random().toString(36).slice(2)}`,
	);
	mkdirSync(dir, { recursive: true });
	return dir;
}

/**
 * Write an executable stub to `dir/name` that runs `script` via bash.
 */
function writeStub(dir: string, name: string, script: string): void {
	const path = join(dir, name);
	writeFileSync(path, `#!/bin/bash\n${script}\n`);
	chmodSync(path, 0o755);
}

async function runInstallSh(
	pathOverride: string,
): Promise<{ exitCode: number; stdout: string; stderr: string }> {
	const proc = Bun.spawn({
		cmd: ["bash", INSTALL_SH],
		env: {
			PATH: pathOverride,
			HOME: process.env.HOME ?? "/tmp",
			SHELL: "/bin/bash",
			CI: "1",
		},
		stdout: "pipe",
		stderr: "pipe",
		stdin: "ignore",
	});
	const [stdout, stderr] = await Promise.all([
		new Response(proc.stdout).text(),
		new Response(proc.stderr).text(),
	]);
	const exitCode = await proc.exited;
	return { exitCode, stdout, stderr };
}

let binDir: string;

beforeEach(() => {
	binDir = makeTmpBinDir();
});

afterEach(() => {
	rmSync(binDir, { recursive: true, force: true });
});

describe("install.sh — exit codes", () => {
	test("exists at repo root", () => {
		expect(existsSync(INSTALL_SH)).toBe(true);
	});

	test("exit 10 when no package manager is found", async () => {
		// PATH has nothing — no bun, npm, pnpm, yarn, no maina, no claude, etc.
		// But we need `bash`, `grep`, `uname`, `mkdir`, `echo` — use a minimal
		// path that includes /bin and /usr/bin only, no node-ish tools. On macOS
		// those aren't in /bin either, so assemble a tiny dir with just coreutils
		// shims by using the system path stripped of typical node installs. Since
		// we can't cleanly isolate, we skip this test when a package manager is
		// on the default $PATH.
		const system = "/usr/bin:/bin";
		const { exitCode, stdout, stderr } = await runInstallSh(system);
		// On hosts where bun/npm/pnpm/yarn are installed in /usr/bin (rare), this
		// test will not produce exit 10. Guard with an early return in that case.
		const hasPm = /Package manager: (bun|pnpm|yarn|npm)/.test(stdout + stderr);
		if (hasPm) return;
		expect(exitCode).toBe(10);
	});

	test("exit 11 when bun install fails", async () => {
		// Fake bun that fails on `install -g`
		writeStub(
			binDir,
			"bun",
			'if [ "$1" = "install" ] && [ "$2" = "-g" ]; then\n  echo "bun install failed (mock)" >&2\n  exit 1\nfi\necho "1.0.0"',
		);
		const { exitCode, stdout, stderr } = await runInstallSh(
			`${binDir}:/usr/bin:/bin`,
		);
		expect(exitCode).toBe(11);
		expect(stdout + stderr).toContain("npm install -g");
	});

	test("exit 12 when install succeeds but maina is not on PATH", async () => {
		// Fake bun that "succeeds" on install -g but does not put maina anywhere
		writeStub(binDir, "bun", "exit 0");
		const { exitCode, stdout, stderr } = await runInstallSh(
			`${binDir}:/usr/bin:/bin`,
		);
		expect(exitCode).toBe(12);
		const combined = stdout + stderr;
		// Must include either the zsh, bash, or fish profile hint
		expect(combined).toMatch(/\.zshrc|\.bashrc|config\.fish|shell profile/);
		// Must include the PATH export hint
		expect(combined).toMatch(/bun\/bin/);
	});

	test("no silent bunx fallback when install succeeds but PATH missing", async () => {
		writeStub(binDir, "bun", "exit 0");
		writeStub(binDir, "bunx", 'echo "1.0.0"');
		const { exitCode, stdout } = await runInstallSh(`${binDir}:/usr/bin:/bin`);
		expect(exitCode).toBe(12);
		// The old behaviour announced "available via bunx" — must be gone.
		expect(stdout).not.toContain("available via bunx");
	});
});

/**
 * `maina sync push` — Upload local prompts to maina cloud.
 * `maina sync pull` — Download team prompts from maina cloud.
 */

import { createHash } from "node:crypto";
import {
	existsSync,
	mkdirSync,
	readdirSync,
	readFileSync,
	writeFileSync,
} from "node:fs";
import { join } from "node:path";
import { intro, log, outro, spinner } from "@clack/prompts";
import type { PromptRecord } from "@mainahq/core";
import { createCloudClient, loadAuthConfig } from "@mainahq/core";
import { Command } from "commander";

// ── Constants ───────────────────────────────────────────────────────────────

const DEFAULT_CLOUD_URL =
	process.env.MAINA_CLOUD_URL ?? "https://api.mainahq.com";

// ── Helpers ─────────────────────────────────────────────────────────────────

function hashContent(content: string): string {
	return createHash("sha256").update(content).digest("hex");
}

function loadLocalPrompts(promptsDir: string): PromptRecord[] {
	if (!existsSync(promptsDir)) {
		return [];
	}

	const files = readdirSync(promptsDir).filter((f) => f.endsWith(".md"));
	return files.map((file) => {
		const filePath = join(promptsDir, file);
		const content = readFileSync(filePath, "utf-8");
		return {
			id: file.replace(/\.md$/, ""),
			name: file.replace(/\.md$/, ""),
			path: file,
			content,
			hash: hashContent(content),
			updatedAt: new Date().toISOString(),
		};
	});
}

// ── Push Action ─────────────────────────────────────────────────────────────

export interface SyncActionResult {
	synced: boolean;
	count: number;
	reason?: string;
}

export async function syncPushAction(cwd?: string): Promise<SyncActionResult> {
	const root = cwd ?? process.cwd();
	const promptsDir = join(root, ".maina", "prompts");

	const authResult = loadAuthConfig();
	if (!authResult.ok) {
		return { synced: false, count: 0, reason: authResult.error };
	}

	const prompts = loadLocalPrompts(promptsDir);
	if (prompts.length === 0) {
		return {
			synced: false,
			count: 0,
			reason: "No prompts found in .maina/prompts/",
		};
	}

	const client = createCloudClient({
		baseUrl: DEFAULT_CLOUD_URL,
		token: authResult.value.accessToken,
	});

	const result = await client.putPrompts(prompts);
	if (!result.ok) {
		const errMsg =
			typeof result.error === "string"
				? result.error
				: JSON.stringify(result.error);
		return { synced: false, count: 0, reason: errMsg };
	}

	return { synced: true, count: prompts.length };
}

// ── Pull Action ─────────────────────────────────────────────────────────────

export async function syncPullAction(cwd?: string): Promise<SyncActionResult> {
	const root = cwd ?? process.cwd();
	const promptsDir = join(root, ".maina", "prompts");

	const authResult = loadAuthConfig();
	if (!authResult.ok) {
		return { synced: false, count: 0, reason: authResult.error };
	}

	const client = createCloudClient({
		baseUrl: DEFAULT_CLOUD_URL,
		token: authResult.value.accessToken,
	});

	const result = await client.getPrompts();
	if (!result.ok) {
		const errMsg =
			typeof result.error === "string"
				? result.error
				: JSON.stringify(result.error);
		return { synced: false, count: 0, reason: errMsg };
	}

	const prompts = result.value ?? [];
	if (prompts.length === 0) {
		return {
			synced: true,
			count: 0,
			reason: "No team prompts yet.",
		};
	}

	try {
		mkdirSync(promptsDir, { recursive: true });
	} catch (e) {
		return {
			synced: false,
			count: 0,
			reason: `Could not create ${promptsDir}: ${e instanceof Error ? e.message : String(e)}`,
		};
	}

	let written = 0;
	const skipped: string[] = [];

	for (const prompt of prompts) {
		// Defensive: a malformed server payload (missing path/content) used to
		// throw out of the loop and leave `@clack/prompts`' spinner monitor to
		// print a generic "Something went wrong" (see #196).
		if (typeof prompt?.path !== "string" || prompt.path.length === 0) {
			skipped.push(`<unknown id=${String(prompt?.id ?? "?")}>`);
			continue;
		}
		if (typeof prompt.content !== "string") {
			skipped.push(prompt.path);
			continue;
		}

		try {
			const filePath = join(promptsDir, prompt.path);
			writeFileSync(filePath, prompt.content, "utf-8");
			written++;
		} catch (e) {
			skipped.push(
				`${prompt.path} (${e instanceof Error ? e.message : String(e)})`,
			);
		}
	}

	if (written === 0 && skipped.length > 0) {
		return {
			synced: false,
			count: 0,
			reason: `All ${skipped.length} prompt(s) skipped: ${skipped.join(", ")}`,
		};
	}

	return {
		synced: true,
		count: written,
		reason:
			skipped.length > 0
				? `Skipped ${skipped.length}: ${skipped.join(", ")}`
				: undefined,
	};
}

// ── Commander Command ───────────────────────────────────────────────────────

export function syncCommand(): Command {
	const cmd = new Command("sync").description("Sync prompts with maina cloud");

	cmd
		.command("push")
		.description("Upload local prompts to the cloud")
		.action(async () => {
			intro("maina sync push");

			const s = spinner();
			s.start("Uploading prompts...");

			const result = await syncPushAction();

			if (result.synced) {
				s.stop("Done");
				log.success(`Pushed ${result.count} prompt(s) to cloud.`);
				outro("Sync complete.");
			} else {
				s.stop("Failed");
				log.error(
					typeof result.reason === "string"
						? result.reason
						: String(result.reason ?? "Unknown error"),
				);
				outro("Sync failed.");
			}
		});

	cmd
		.command("pull")
		.description("Download team prompts from the cloud")
		.action(async () => {
			intro("maina sync pull");

			const s = spinner();
			s.start("Downloading prompts...");

			const result = await syncPullAction();

			if (result.synced) {
				s.stop("Done");
				if (result.count === 0 && result.reason) {
					// Empty team — show the friendly message instead of "Pulled 0".
					log.info(result.reason);
				} else {
					log.success(`Pulled ${result.count} prompt(s) from cloud.`);
					if (result.reason) {
						// Partial success: some records were malformed and skipped.
						log.warning(result.reason);
					}
				}
				outro("Sync complete.");
			} else {
				s.stop("Failed");
				log.error(
					typeof result.reason === "string"
						? result.reason
						: String(result.reason ?? "Unknown error"),
				);
				outro("Sync failed.");
			}
		});

	return cmd;
}

#!/usr/bin/env bun
/**
 * Wave 4 / G11 — build-time SSOT for "how many commands, MCP tools,
 * skills does maina ship?".
 *
 * Two modes:
 *
 *   bun scripts/docs-manifest.ts
 *     Emit a JSON manifest on stdout. Used for docs/landing copy
 *     generation — never hand-typed.
 *
 *   bun scripts/docs-manifest.ts --check
 *     Grep README.md and packages/docs/src/content/docs/**.md{,x} for
 *     hand-typed `N commands` / `N MCP tools` / `N skills` patterns.
 *     Fail with exit 1 and a pointer to the manifest if any match.
 *
 * The number-extractor is a simple regex; prose like "nine commands"
 * (spelled-out number) does not match, so legitimate text is safe.
 */

import { readdirSync, readFileSync, statSync } from "node:fs";
import { join, relative } from "node:path";

const ROOT = join(import.meta.dir, "..");

// ── Sources of truth ────────────────────────────────────────────────────────

function countVisibleCommands(): number {
	const path = join(ROOT, "packages", "cli", "src", "program.ts");
	const body = readFileSync(path, "utf-8");

	// Everything between `// ── Workflow` (first block) and
	// `// ── Internals` is user-facing.
	const start = body.indexOf("// ── Workflow");
	const end = body.indexOf("// ── Internals");
	if (start < 0 || end < 0 || end <= start) {
		throw new Error(
			"docs-manifest: could not locate Workflow/Internals section markers in program.ts",
		);
	}
	const visible = body.slice(start, end);
	const matches = visible.match(/program\.addCommand\(/g) ?? [];
	return matches.length;
}

function countMcpTools(): number {
	const path = join(ROOT, "packages", "mcp", "src", "server.ts");
	const body = readFileSync(path, "utf-8");
	// `ALL_TOOL_DESCRIPTIONS` is the canonical list. We parse the array
	// literal length by counting occurrences of `name: "` after its
	// opening.
	const start = body.indexOf("ALL_TOOL_DESCRIPTIONS");
	if (start < 0) {
		throw new Error(
			"docs-manifest: ALL_TOOL_DESCRIPTIONS not found in server.ts",
		);
	}
	const end = body.indexOf("];", start);
	const block = body.slice(start, end);
	const matches = block.match(/name:\s*"/g) ?? [];
	return matches.length;
}

function listSkills(): string[] {
	const root = join(ROOT, "packages", "skills");
	const out: string[] = [];
	let entries: string[];
	try {
		entries = readdirSync(root);
	} catch {
		return out;
	}
	for (const name of entries) {
		const full = join(root, name);
		try {
			if (!statSync(full).isDirectory()) continue;
		} catch {
			continue;
		}
		const skillPath = join(full, "SKILL.md");
		try {
			if (statSync(skillPath).isFile()) out.push(name);
		} catch {
			// skip
		}
	}
	return out.sort();
}

function listMcpToolNames(): string[] {
	const path = join(ROOT, "packages", "mcp", "src", "server.ts");
	const body = readFileSync(path, "utf-8");
	const start = body.indexOf("ALL_TOOL_DESCRIPTIONS");
	const end = body.indexOf("];", start);
	const block = body.slice(start, end);
	const names: string[] = [];
	const re = /name:\s*"([^"]+)"/g;
	let m: RegExpExecArray | null;
	// biome-ignore lint/suspicious/noAssignInExpressions: idiomatic regex scan
	while ((m = re.exec(block)) !== null) {
		names.push(m[1] ?? "");
	}
	return names.filter((n) => n.length > 0);
}

function listVisibleCommandNames(): string[] {
	const path = join(ROOT, "packages", "cli", "src", "program.ts");
	const body = readFileSync(path, "utf-8");
	const start = body.indexOf("// ── Workflow");
	const end = body.indexOf("// ── Internals");
	const visible = body.slice(start, end);
	const names: string[] = [];
	const re = /program\.addCommand\((\w+)Command\(/g;
	let m: RegExpExecArray | null;
	// biome-ignore lint/suspicious/noAssignInExpressions: idiomatic regex scan
	while ((m = re.exec(visible)) !== null) {
		names.push(m[1] ?? "");
	}
	return names.filter((n) => n.length > 0);
}

// ── Manifest build ──────────────────────────────────────────────────────────

export interface DocsManifest {
	generatedAt: string;
	commands: {
		visible: number;
		names: string[];
	};
	mcpTools: {
		total: number;
		names: string[];
	};
	skills: {
		total: number;
		names: string[];
	};
}

export function buildManifest(): DocsManifest {
	const commandNames = listVisibleCommandNames();
	const toolNames = listMcpToolNames();
	const skillNames = listSkills();
	return {
		generatedAt: new Date().toISOString(),
		commands: {
			visible: countVisibleCommands(),
			names: commandNames,
		},
		mcpTools: {
			total: countMcpTools(),
			names: toolNames,
		},
		skills: {
			total: skillNames.length,
			names: skillNames,
		},
	};
}

// ── --check mode ────────────────────────────────────────────────────────────

const CHECK_PATTERN = /\b(\d+)\s+(commands|MCP tools|skills)\b/gi;

/** Files we scan for hand-typed counts. */
function checkTargets(): string[] {
	const targets: string[] = [join(ROOT, "README.md")];
	const docsRoot = join(ROOT, "packages", "docs", "src", "content", "docs");
	try {
		walkMarkdown(docsRoot, targets);
	} catch {
		// docs package optional
	}
	return targets;
}

function walkMarkdown(dir: string, out: string[]): void {
	let entries: string[];
	try {
		entries = readdirSync(dir);
	} catch {
		return;
	}
	for (const name of entries) {
		const full = join(dir, name);
		let stats: ReturnType<typeof statSync>;
		try {
			stats = statSync(full);
		} catch {
			continue;
		}
		if (stats.isDirectory()) {
			walkMarkdown(full, out);
			continue;
		}
		if (!stats.isFile()) continue;
		if (!name.endsWith(".md") && !name.endsWith(".mdx")) continue;
		out.push(full);
	}
}

interface CheckHit {
	file: string;
	line: number;
	text: string;
}

function runCheck(): number {
	const manifest = buildManifest();
	const hits: CheckHit[] = [];
	for (const file of checkTargets()) {
		let body: string;
		try {
			body = readFileSync(file, "utf-8");
		} catch {
			continue;
		}
		const lines = body.split(/\r?\n/);
		for (let i = 0; i < lines.length; i++) {
			const line = lines[i] ?? "";
			// Skip ignore-annotated lines (HTML comment for .md, JSX comment for
			// .mdx). The annotation must appear on the line immediately before
			// the hand-typed count OR on the same line.
			const prev = i > 0 ? (lines[i - 1] ?? "") : "";
			const ignoreMarker =
				/<!--\s*docs-manifest:\s*ignore\s*-->|\{\/\*\s*docs-manifest:\s*ignore\s*\*\/\}/i;
			if (ignoreMarker.test(line) || ignoreMarker.test(prev)) continue;
			const matches = line.matchAll(CHECK_PATTERN);
			for (const _m of matches) {
				hits.push({ file, line: i + 1, text: line.trim() });
			}
		}
	}
	if (hits.length === 0) {
		// eslint-disable-next-line no-console
		console.log(
			"docs-manifest --check: OK — no hand-typed counts in docs sources.",
		);
		// eslint-disable-next-line no-console
		console.log(
			`Live counts → commands=${manifest.commands.visible} mcpTools=${manifest.mcpTools.total} skills=${manifest.skills.total}`,
		);
		return 0;
	}
	// eslint-disable-next-line no-console
	console.error(
		`docs-manifest --check: FAIL — ${hits.length} hand-typed count(s) detected.`,
	);
	for (const h of hits) {
		// eslint-disable-next-line no-console
		console.error(`  ${relative(ROOT, h.file)}:${h.line}  ${h.text}`);
	}
	// eslint-disable-next-line no-console
	console.error(
		"\nFix: remove the hand-typed numbers and link readers to `bun run docs:manifest`.",
	);
	// eslint-disable-next-line no-console
	console.error(
		`Live counts → commands=${manifest.commands.visible} mcpTools=${manifest.mcpTools.total} skills=${manifest.skills.total}`,
	);
	return 1;
}

// ── Entrypoint ──────────────────────────────────────────────────────────────

function main(): void {
	const args = process.argv.slice(2);
	if (args.includes("--check")) {
		process.exit(runCheck());
	}
	const manifest = buildManifest();
	// eslint-disable-next-line no-console
	console.log(JSON.stringify(manifest, null, 2));
}

if (import.meta.main) {
	main();
}

/**
 * AI Review — semantic code review using LLM.
 *
 * Two tiers:
 * - mechanical (always-on): diff + referenced functions, <3s, warnings only
 * - standard (--deep): adds spec/plan context, can emit errors
 */

import type { Finding } from "./diff-filter";

// ─── Types ────────────────────────────────────────────────────────────────

export interface ReferencedFunction {
  name: string;
  filePath: string;
  body: string;
}

export interface EntityWithBody {
  name: string;
  kind: string;
  startLine: number;
  endLine: number;
  filePath: string;
  body: string;
}

export interface AIReviewOptions {
  diff: string;
  entities: EntityWithBody[];
  deep?: boolean;
  specContext?: string;
  planContext?: string;
  mainaDir: string;
}

export interface AIReviewResult {
  findings: Finding[];
  skipped: boolean;
  tier: "mechanical" | "standard";
  duration: number;
}

const MAX_REFS_PER_FILE = 3;

// ─── Referenced Function Resolution ───────────────────────────────────────

/**
 * Extract function/method names called in added lines of a diff,
 * then match them against known entities to get their bodies.
 * Capped at MAX_REFS_PER_FILE (3) to bound token usage.
 */
export function resolveReferencedFunctions(
  diff: string,
  entities: EntityWithBody[],
): ReferencedFunction[] {
  // Extract added lines from diff
  const addedLines = diff
    .split("\n")
    .filter((line) => line.startsWith("+") && !line.startsWith("+++"))
    .join("\n");

  if (!addedLines.trim()) return [];

  // Extract identifier-like tokens that could be function calls
  // Match word( pattern — likely a function call
  const callPattern = /\b([a-zA-Z_$][\w$]*)\s*\(/g;
  const calledNames = new Set<string>();
  for (const match of addedLines.matchAll(callPattern)) {
    if (match[1]) calledNames.add(match[1]);
  }

  // Remove common keywords that match the pattern
  const KEYWORDS = new Set([
    "if", "for", "while", "switch", "catch", "function", "return",
    "new", "typeof", "instanceof", "await", "async", "import", "export",
    "const", "let", "var", "class", "throw",
  ]);
  for (const kw of KEYWORDS) calledNames.delete(kw);

  if (calledNames.size === 0) return [];

  // Match against known entities
  const matched: ReferencedFunction[] = [];
  for (const entity of entities) {
    if (matched.length >= MAX_REFS_PER_FILE) break;
    if (calledNames.has(entity.name)) {
      matched.push({
        name: entity.name,
        filePath: entity.filePath,
        body: entity.body,
      });
    }
  }

  return matched;
}

