/**
 * `maina mcp` — install, remove, and list the maina MCP server across
 * supported AI clients.
 *
 * Public entry points: `runAdd`, `runRemove`, `runList`. Each takes a
 * RunOptions describing the requested clients, scope, dry-run mode, and
 * cwd. Each returns a per-client list of ApplyResult / status records.
 */

import { addOnClient, inspectClient, removeFromClient } from "./apply";
import { buildClientRegistry, listClientIds } from "./clients";
import type { ApplyResult, McpClientId, RunOptions } from "./types";

export { buildClientRegistry, listClientIds } from "./clients";
export type {
	ApplyResult,
	McpClientId,
	McpClientInfo,
	McpScope,
	RunOptions,
} from "./types";

interface ResolvedClient {
	id: McpClientId;
	configPath: string;
	scope: "global" | "project";
}

async function selectClients(
	opts: RunOptions,
): Promise<{ targets: ResolvedClient[]; skipped: McpClientId[] }> {
	const registry = buildClientRegistry(opts.home);
	const requested = opts.clients ?? listClientIds();
	const targets: ResolvedClient[] = [];
	const skipped: McpClientId[] = [];

	for (const id of requested) {
		const info = registry[id];
		// When the user explicitly named clients, respect the choice and
		// skip detection. Auto-mode (no --client list) only writes to
		// clients we believe are present.
		const explicit = opts.clients !== undefined;
		if (!explicit) {
			const installed = await info.detect();
			if (!installed) {
				skipped.push(id);
				continue;
			}
		}
		if (opts.scope === "global" || opts.scope === "both") {
			targets.push({
				id,
				configPath: info.globalConfigPath(),
				scope: "global",
			});
		}
		if (
			(opts.scope === "project" || opts.scope === "both") &&
			info.projectConfigPath
		) {
			targets.push({
				id,
				configPath: info.projectConfigPath(opts.cwd),
				scope: "project",
			});
		}
	}
	return { targets, skipped };
}

export interface RunReport {
	results: ApplyResult[];
	skipped: McpClientId[];
}

export async function runAdd(opts: RunOptions): Promise<RunReport> {
	const registry = buildClientRegistry(opts.home);
	const { targets, skipped } = await selectClients(opts);
	const results: ApplyResult[] = [];
	for (const t of targets) {
		const info = registry[t.id];
		results.push(
			await addOnClient(info, {
				configPath: t.configPath,
				scope: t.scope,
				dryRun: opts.dryRun,
			}),
		);
	}
	return { results, skipped };
}

export async function runRemove(opts: RunOptions): Promise<RunReport> {
	const registry = buildClientRegistry(opts.home);
	const { targets, skipped } = await selectClients(opts);
	const results: ApplyResult[] = [];
	for (const t of targets) {
		const info = registry[t.id];
		results.push(
			await removeFromClient(info, {
				configPath: t.configPath,
				scope: t.scope,
				dryRun: opts.dryRun,
			}),
		);
	}
	return { results, skipped };
}

export interface ListEntry {
	clientId: McpClientId;
	label: string;
	scope: "global" | "project";
	configPath: string;
	detected: boolean;
	installed: boolean;
	error?: string;
}

export async function runList(
	opts: RunOptions,
): Promise<{ entries: ListEntry[] }> {
	const registry = buildClientRegistry(opts.home);
	const requested = opts.clients ?? listClientIds();
	const entries: ListEntry[] = [];
	for (const id of requested) {
		const info = registry[id];
		const detected = await info.detect();
		const scopes: Array<"global" | "project"> =
			opts.scope === "both"
				? ["global", "project"]
				: opts.scope === "project"
					? ["project"]
					: ["global"];
		for (const scope of scopes) {
			// If a client doesn't define a project-scope config path, skip
			// the project entry entirely rather than silently reporting the
			// global path with `scope: "project"` (which would mislead users
			// who explicitly asked for `--scope project`).
			if (scope === "project" && !info.projectConfigPath) continue;
			const path =
				scope === "project" && info.projectConfigPath
					? info.projectConfigPath(opts.cwd)
					: info.globalConfigPath();
			const status = await inspectClient(info, path);
			entries.push({
				clientId: id,
				label: info.label,
				scope,
				configPath: path,
				detected,
				installed: status.installed,
				...(status.error ? { error: status.error } : {}),
			});
		}
	}
	return { entries };
}

import type { Result } from "../db/index";
import type { BenchmarkMetrics } from "./types";

export interface TestResult {
	passed: number;
	failed: number;
	total: number;
}

export interface RunBenchmarkOptions {
	pipeline: "maina" | "speckit";
	storyName: string;
	testFiles: string[];
	implDir: string;
	tokensInput?: number;
	tokensOutput?: number;
	verifyFindings?: number;
	specQualityScore?: number;
	implLOC?: number;
	attemptsToPass?: number;
	bugsIntroduced?: number;
	toolsUsed?: string[];
}

/**
 * Parse bun test stdout to extract pass/fail counts.
 */
export function parseTestOutput(output: string): TestResult {
	const passMatch = output.match(/(\d+)\s+pass/);
	const failMatch = output.match(/(\d+)\s+fail/);

	const passed = passMatch ? Number.parseInt(passMatch[1] as string, 10) : 0;
	const failed = failMatch ? Number.parseInt(failMatch[1] as string, 10) : 0;

	return { passed, failed, total: passed + failed };
}

/**
 * Run benchmark tests against an implementation directory.
 * Spawns `bun test` on the provided test files and captures metrics.
 */
export async function runBenchmark(
	options: RunBenchmarkOptions,
): Promise<Result<BenchmarkMetrics>> {
	const startMs = performance.now();

	try {
		const proc = Bun.spawn(["bun", "test", ...options.testFiles], {
			cwd: options.implDir,
			stdout: "pipe",
			stderr: "pipe",
			env: {
				...process.env,
				MITT_IMPL_PATH: options.implDir,
			},
		});

		const stdout = await new Response(proc.stdout).text();
		const stderr = await new Response(proc.stderr).text();
		await proc.exited;

		const combined = stdout + stderr;
		const testResult = parseTestOutput(combined);
		const wallClockMs = Math.round(performance.now() - startMs);

		return {
			ok: true,
			value: {
				pipeline: options.pipeline,
				storyName: options.storyName,
				wallClockMs,
				tokensInput: options.tokensInput ?? 0,
				tokensOutput: options.tokensOutput ?? 0,
				testsTotal: testResult.total,
				testsPassed: testResult.passed,
				testsFailed: testResult.failed,
				verifyFindings: options.verifyFindings ?? 0,
				specQualityScore: options.specQualityScore ?? 0,
				implLOC: options.implLOC ?? 0,
				attemptsToPass: options.attemptsToPass ?? 1,
				bugsIntroduced: options.bugsIntroduced ?? 0,
				toolsUsed: options.toolsUsed ?? [],
			},
		};
	} catch (e) {
		return {
			ok: false,
			error: `Benchmark run failed: ${e instanceof Error ? e.message : String(e)}`,
		};
	}
}

/**
 * Rule confirmation — TTY y/n/e UI + non-TTY auto-accept.
 *
 * TTY path: lazily imports `@clack/prompts` (a CLI-layer dep, not a core
 * dep) and asks y/n/e per rule. The `e` branch opens `$EDITOR` to let the
 * user rewrite the rule before accepting.
 *
 * Non-TTY path: auto-accepts rules at or above `autoAcceptThreshold`
 * (default 0.6) and rejects the rest. No stdin reads, safe for CI.
 *
 * Rejected rules are appended (de-duplicated) to `.maina/rejected.yml` so
 * future setup re-runs can re-surface them if their confidence rises.
 */

import {
	existsSync,
	mkdirSync,
	readFileSync,
	unlinkSync,
	writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import type { Rule } from "./adopt";

export interface ConfirmOptions {
	/** Default: `process.stdout.isTTY`. */
	interactive?: boolean;
	/** Non-TTY default: 0.6. Range 0..1. */
	autoAcceptThreshold?: number;
	/** Where `rejected.yml` lives. Default: `<cwd>/.maina`. */
	mainaDir?: string;
	/** Injection point for tests — replaces `@clack/prompts.select`. */
	promptImpl?: (rule: Rule) => Promise<"y" | "n" | "e">;
	/** Injection point for tests — replaces the `$EDITOR` invocation. */
	editImpl?: (rule: Rule) => Promise<Rule>;
	/** Override `Date.now()` for deterministic tests. */
	nowIso?: () => string;
}

export interface ConfirmResult {
	accepted: Rule[];
	rejected: Rule[];
}

export async function confirmRules(
	rules: Rule[],
	opts: ConfirmOptions = {},
): Promise<ConfirmResult> {
	if (rules.length === 0) {
		return { accepted: [], rejected: [] };
	}

	const interactive =
		opts.interactive !== undefined
			? opts.interactive
			: typeof process !== "undefined" && Boolean(process.stdout.isTTY);
	const threshold = opts.autoAcceptThreshold ?? 0.6;
	const mainaDir = opts.mainaDir ?? join(process.cwd(), ".maina");

	const accepted: Rule[] = [];
	const rejected: Rule[] = [];

	if (interactive) {
		const selectRule = opts.promptImpl ?? (await loadClackPrompt());
		for (const rule of rules) {
			const verdict = await selectRule(rule);
			if (verdict === "y") {
				accepted.push(rule);
			} else if (verdict === "n") {
				rejected.push(rule);
			} else if (verdict === "e") {
				const edited = opts.editImpl
					? await opts.editImpl(rule)
					: await openEditor(rule);
				accepted.push(edited);
			}
		}
	} else {
		for (const rule of rules) {
			if (rule.confidence >= threshold) {
				accepted.push(rule);
			} else {
				rejected.push(rule);
			}
		}
	}

	if (rejected.length > 0) {
		appendRejected(
			mainaDir,
			rejected,
			opts.nowIso ?? (() => new Date().toISOString()),
		);
	}

	return { accepted, rejected };
}

// ── rejected.yml ─────────────────────────────────────────────────────────────

interface RejectedEntry {
	text: string;
	source: string;
	confidence: number;
	rejectedAt: string;
}

function appendRejected(
	mainaDir: string,
	rules: Rule[],
	nowIso: () => string,
): void {
	try {
		if (!existsSync(mainaDir)) {
			mkdirSync(mainaDir, { recursive: true });
		}
	} catch {
		return;
	}
	const path = join(mainaDir, "rejected.yml");
	const existing = parseRejected(safeRead(path) ?? "");
	const seen = new Set(existing.map((e) => normalise(e.text)));
	const ts = nowIso();
	for (const rule of rules) {
		const key = normalise(rule.text);
		if (seen.has(key)) continue;
		existing.push({
			text: rule.text,
			source: rule.source,
			confidence: rule.confidence,
			rejectedAt: ts,
		});
		seen.add(key);
	}
	writeRejected(path, existing);
}

function writeRejected(path: string, entries: RejectedEntry[]): void {
	const lines: string[] = ["# maina rejected rules", "rules:"];
	for (const e of entries) {
		lines.push(`  - text: ${yamlString(e.text)}`);
		lines.push(`    source: ${yamlString(e.source)}`);
		lines.push(`    confidence: ${e.confidence}`);
		lines.push(`    rejectedAt: ${yamlString(e.rejectedAt)}`);
	}
	try {
		writeFileSync(path, `${lines.join("\n")}\n`, "utf-8");
	} catch {
		// Swallow — a read-only filesystem must not abort setup.
	}
}

function parseRejected(yaml: string): RejectedEntry[] {
	const out: RejectedEntry[] = [];
	const lines = yaml.split("\n");
	let cur: Partial<RejectedEntry> | null = null;
	for (const raw of lines) {
		const line = raw.replace(/\r$/, "");
		if (/^\s*- text:/.test(line)) {
			if (cur?.text) out.push(cur as RejectedEntry);
			cur = { text: extractYamlValue(line) };
		} else if (cur && /^\s*source:/.test(line)) {
			cur.source = extractYamlValue(line);
		} else if (cur && /^\s*confidence:/.test(line)) {
			const v = Number.parseFloat(extractYamlValue(line));
			cur.confidence = Number.isFinite(v) ? v : 0;
		} else if (cur && /^\s*rejectedAt:/.test(line)) {
			cur.rejectedAt = extractYamlValue(line);
		}
	}
	if (cur?.text) out.push(cur as RejectedEntry);
	return out.filter(
		(e): e is RejectedEntry =>
			typeof e.text === "string" &&
			typeof e.source === "string" &&
			typeof e.confidence === "number" &&
			typeof e.rejectedAt === "string",
	);
}

function extractYamlValue(line: string): string {
	const idx = line.indexOf(":");
	if (idx === -1) return "";
	const rest = line.slice(idx + 1).trim();
	// Remove surrounding quotes if present.
	if (
		(rest.startsWith('"') && rest.endsWith('"')) ||
		(rest.startsWith("'") && rest.endsWith("'"))
	) {
		return rest.slice(1, -1).replace(/\\"/g, '"');
	}
	return rest;
}

function yamlString(s: string): string {
	// Quote if it contains characters that need quoting.
	if (/[:#\n"']/.test(s) || s.startsWith(" ") || s.endsWith(" ")) {
		return `"${s.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;
	}
	return s;
}

function normalise(s: string): string {
	return s
		.toLowerCase()
		.replace(/\s+/g, " ")
		.replace(/[.!?]+$/u, "")
		.trim();
}

function safeRead(path: string): string | null {
	try {
		return readFileSync(path, "utf-8");
	} catch {
		return null;
	}
}

// ── TTY plumbing ─────────────────────────────────────────────────────────────

/**
 * Lazily load `@clack/prompts`. Falls back to a non-interactive accepter if
 * the package is not installed (it's a CLI-layer dep, not a core dep).
 */
async function loadClackPrompt(): Promise<
	(rule: Rule) => Promise<"y" | "n" | "e">
> {
	try {
		// `@clack/prompts` is a CLI-layer dependency — core does not declare it,
		// so we dynamic-import via a computed specifier to suppress bundler
		// resolution at typecheck time.
		const spec = "@clack/prompts";
		const mod = (await import(/* @vite-ignore */ spec)) as unknown as {
			select: (input: {
				message: string;
				options: { value: string; label: string; hint?: string }[];
				initialValue?: string;
			}) => Promise<string | symbol>;
			isCancel: (v: unknown) => boolean;
		};
		return async (rule: Rule) => {
			const answer = await mod.select({
				message: `Rule: "${rule.text}"\nSource: ${rule.source} | Confidence: ${rule.confidence.toFixed(2)}`,
				options: [
					{ value: "y", label: "yes, keep it" },
					{ value: "n", label: "no, drop it" },
					{ value: "e", label: "edit" },
				],
				initialValue: rule.confidence >= 0.6 ? "y" : "n",
			});
			if (mod.isCancel(answer)) return "n";
			return answer === "e" ? "e" : answer === "y" ? "y" : "n";
		};
	} catch {
		// Fallback: treat as non-interactive with 0.6 threshold.
		return async (rule: Rule) =>
			rule.confidence >= 0.6 ? ("y" as const) : ("n" as const);
	}
}

async function openEditor(rule: Rule): Promise<Rule> {
	// Write the current rule text to a temp file, spawn $EDITOR (falling back
	// to `vi`), and read the edited text back. If anything fails — missing
	// editor, non-zero exit, empty edit — we keep the original rule rather
	// than dropping user-authored content silently.
	const editorRaw = process.env.VISUAL ?? process.env.EDITOR ?? "vi";
	// `$VISUAL` / `$EDITOR` routinely carry args: `code --wait`, `vim -u NONE`,
	// `emacs -nw`, etc. Passing the whole string as argv[0] would make Bun
	// look for a binary literally named `"code --wait"`. We tokenise on
	// whitespace; quoted editor strings aren't part of the standard contract
	// (`git`/`VISUAL` conventions are whitespace-separated) so we don't
	// attempt full shell-word parsing.
	const editorArgv = editorRaw
		.trim()
		.split(/\s+/)
		.filter((s) => s.length > 0);
	if (editorArgv.length === 0) return rule;
	const tmp = join(
		tmpdir(),
		`maina-rule-${Date.now()}-${Math.random().toString(36).slice(2)}.txt`,
	);
	const header =
		"# Edit the rule below. Lines starting with `#` are ignored.\n" +
		`# Source: ${rule.source}\n` +
		`# Confidence: ${rule.confidence.toFixed(2)}\n\n`;
	try {
		writeFileSync(tmp, header + rule.text + "\n");
		const proc = Bun.spawn({
			cmd: [...editorArgv, tmp],
			stdin: "inherit",
			stdout: "inherit",
			stderr: "inherit",
		});
		const code = await proc.exited;
		if (code !== 0) return rule;
		const raw = readFileSync(tmp, "utf-8");
		const edited = raw
			.split(/\r?\n/)
			.filter((l) => !l.startsWith("#"))
			.join("\n")
			.trim();
		if (edited.length === 0) return rule;
		return { ...rule, text: edited };
	} catch {
		return rule;
	} finally {
		try {
			unlinkSync(tmp);
		} catch {
			// ignore cleanup failures
		}
	}
}

